30	static void print_cpu_configuration()
31	{
32	  // these symbols are defined in obj_sc/config.o
33	  // they come from andes_ip/kv_core/top/hdl/config.inc
34	  char* start = &_binary_config_inc_start;
35	  char* end = &_binary_config_inc_end;
36	  fwrite(start, 1, end - start, stdout);
37	}
