39	static void print_version()
40	{
41	  fmt::print(
42	    "Copyright (C) 2013-2026 Andes Technology Corporation. All rights reserved.\n");
43	  fmt::print("Version : {}\n\n", ANDESCYCLE_VERSION);
44	
45	  // output ACE, ACERVV support version
46	  if (get_libaceasim_version)
47	    fmt::print("Andes Custom Extension : {}\n", get_libaceasim_version());
48	}
