50	static void print_help()
51	{
52	  print_version();
53	  fmt::print(R"(
54	Usage: sim_cpu_name [elf_file] [options]
55	
56	AndesCycle CPU simulator for RISC-V processors
57	
58	Argument:
59	  <elf_file>                  RISC-V ELF binary to simulate
60	
61	General:
62	  --help, -h                  Print this help message and exit
63	  --version                   Display version information and exit
64	  --print-config              Show CPU configuration and exit
65	  --print-memmap              Show memory map layout and exit
66	  --log-level <level>         Set logging verbosity [default: 2]
67	                              (0=trace 1=debug 2=info 3=warn 4=error 5=critical 6=off)
68	
69	Simulation:
70	  --mem-latency  <cycles>     Memory access latency in cycles [default: 1]
71	  --reset-vector <spec>       Set per-hart reset vector
72	                              <addr>        set all harts to <addr>
73	                              <hart>:<addr> set specific hart to <addr>
74	                              Overrides ELF entrypoint if specified
75	
76	Tracing:
77	  --pc-trace  <file>          Enable PC trace logging to CSV file
78	  --kanata    <file>          Enable Kanata pipeline visualization logging
79	  --clarity   <file>          Enable Clarity pipeline visualization logging
80	  --objdump   <file>          Load objdump disassembly for pipeline viewer labels
81	  --kanata-loop-start <pc>    Start PC of the loop body (hex with 0x ok)
82	  --kanata-loop-end   <pc>    End PC of the loop body. Each retire of this PC
83	                              counts as one iteration; combine with --kanata or
84	                              --clarity to dump a steady-state window
85	  --kanata-loop-skip  <N>     Skip first N iterations [default: 0]
86	  --kanata-loop-record <X>    Record next X iterations then exit [default: 1]
87	  --kanata-roi                Auto-derive the kanata window for the hybrid ROI:
88	                              start_pc = the resumed PC (from
89	                              --resume-from-qemu state), end_pc = --hybrid-exit-pc
90	                              (pc-mode) or the unique `csrwi 0x7C0,1` PC
91	                              scanned from the ELF (csr-mode). Requires
92	                              --kanata; mutually exclusive with
93	                              --kanata-loop-*; incompatible with
94	                              --hybrid-icount.
95	
96	Debug:
97	  --jtag-port <port>          JTAG remote bitbang port for OpenOCD [default: 9104]
98	
99	Extra Options (require additional license):
100	  --ilm       <image>         Load ILM ROM image
101	  --dlm       <image>         Load DLM ROM image
102	  --waveform  <file>          Enable VCD/FST waveform tracing
103	  --save                      Save context when CPU enters WFI
104	  --continue                  Restore context and resume execution
105	  --context-dir <dir>         Context directory [default: ./saved_ctx]
106	
107	Hybrid (QEMU + Verilator):
108	  --shared-mem-path <file>    mmap-backed file used as main RAM (zero-copy
109	                              shared with QEMU). Requires --shared-mem-size.
110	  --shared-mem-size <bytes>   Size of the shared mmap region; must cover the
111	                              full main memory range
112	  --shared-mem-base <hex>     Guest physical address that file offset 0 maps
113	                              to. Default 0x80000000 (QEMU virt RAM base);
114	                              override only for non-virt machine types.
115	  --resume-from-qemu <file>   Resume from a QEMU-side state snapshot.
116	                              Mutually exclusive with --continue.
117	  --handoff-out <file>        Drain architectural state to <file> when
118	                              `csrwi 0x7C0, 1` retires; exit with code 200.
119	  --hybrid-enter-pc <hex>     PC-trigger mode: orchestrator-side entry PC.
120	                              Accepted but IGNORED by vsim - entry is QEMU's
121	                              job (the plugin's `enter_pc=` arg). Logged for
122	                              symmetry with --hybrid-exit-pc.
123	  --hybrid-exit-pc <hex>      PC-trigger mode: drain when an insn at this PC
124	                              retires, instead of pre-scanning the ELF for
125	                              `csrwi 0x7C0, 1`. The binary need not contain
126	                              a magic CSR write.
127	  --hybrid-icount <N>         icount-trigger mode: drain after <N> committed
128	                              insns retire, regardless of PC. Mutually
129	                              exclusive with --hybrid-exit-pc and the
130	                              ELF-scan CSR trigger.
131	  --vsim-warmup-icount <K>    gem5-style warmup window. Snapshot
132	                              (mcycle, minstret) K committed insns after vsim
133	                              entry; the snapshot lands in the drained state
134	                              file's mcycle_at_measure_start /
135	                              minstret_at_measure_start so the orchestrator
136	                              can report cycles excluding the cold-cache
137	                              prefix. K=0 disables (snapshot fields stay 0).
138	                              Mode-agnostic: works with csr / pc / icount.
139	)");
140	  // --ilm/--dlm: CPU-specific, not all CPUs have ILM/DLM
141	  // --waveform: requires compile flag VSIMDEBUG
142	  // --save/--continue/--context-dir: requires compile flag VSIMSAVABLE
143	}
