145	extern "C" auto sc_main(const int argc, char* argv[]) -> int
146	try {
147	  spdlog::set_default_logger(spdlog::stderr_color_mt("stderr_logger"));
148	  spdlog::set_pattern("[%^%l%$] %v");
149	
150	  const auto args = [&] {
151	    struct args
152	    {
153	      std::string pc_trace_file{};
154	      std::string elf_file{};
155	      std::optional<uint16_t> jtag_port = std::nullopt;
156	      bool memmap = false;
157	      std::string waveform_file{};
158	      unsigned mem_latency = 1;
159	      std::string ilm_file{};
160	      std::string dlm_file{};
161	      std::string kanata_file{};
162	      std::string objdump_file{};
163	      std::string clarity_file{};
164	      std::optional<uint64_t> kanata_loop_start{};
165	      std::optional<uint64_t> kanata_loop_end{};
166	      uint64_t kanata_loop_skip = 0;
167	      uint64_t kanata_loop_record = 1;
168	      bool kanata_roi = false;
169	      std::vector<std::string> reset_vectors{};
170	      bool continue_ctx = false;
171	      bool save_ctx = false;
172	      std::string context_dir = "./saved_ctx/";
173	      std::string shared_mem_path{};
174	      uint64_t shared_mem_size = 0;
175	      uint64_t shared_mem_base = 0x80000000;
176	      std::string resume_from_qemu{};
177	      std::string handoff_out{};
178	      std::optional<uint64_t> hybrid_enter_pc{};
179	      std::optional<uint64_t> hybrid_exit_pc{};
180	      std::optional<uint64_t> hybrid_icount{};
181	      uint64_t vsim_warmup_icount = 0;
182	    } args;
183	
184	    const auto help_and_exit = [] {
185	      print_help();
186	      exit(0);
187	    };
188	
189	    auto p = parser{};
190	    p.shortflag('h', help_and_exit);
191	    p.longflag("help", help_and_exit);
192	    p.longflag("version", [] {
193	      print_version();
194	      exit(0);
195	    });
196	    p.longflag("print-memmap", [&] { args.memmap = true; });
197	    p.longflag("print-config", [] {
198	      print_cpu_configuration();
199	      exit(0);
200	    });
201	    p.longopt("jtag-port", [&](const std::string_view s) {
202	      if (auto n = to_int<uint16_t>(s); n)
203	        args.jtag_port = *n;
204	      else
205	        throw std::runtime_error("invalid number for --jtag-port: "
206	                                 + std::string{s});
207	    });
208	    p.longopt("mem-latency", [&](const std::string_view s) {
209	      if (auto n = to_int<unsigned>(s); n)
210	        args.mem_latency = *n;
211	      else
212	        throw std::runtime_error("invalid number for --mem-latency: "
213	                                 + std::string{s});
214	    });
215	    p.longopt("log-level", [](const std::string_view s) {
216	      if (auto n = to_int<uint16_t>(s); n) {
217	        *n = std::min(*n, (uint16_t) SPDLOG_LEVEL_OFF);
218	        spdlog::set_level(static_cast<spdlog::level::level_enum>(*n));
219	      } else {
220	        throw std::runtime_error("invalid number for --log-level: "
221	                                 + std::string{s});
222	      }
223	    });
224	    p.longopt("waveform",
225	              [&](const std::string_view s) { args.waveform_file = s; });
226	    p.longopt("ilm", [&](const std::string_view s) { args.ilm_file = s; });
227	    p.longopt("dlm", [&](const std::string_view s) { args.dlm_file = s; });
228	    p.longopt("pc-trace",
229	              [&](const std::string_view s) { args.pc_trace_file = s; });
230	    p.longopt("kanata",
231	              [&](const std::string_view s) { args.kanata_file = s; });
232	    p.longopt("objdump",
233	              [&](const std::string_view s) { args.objdump_file = s; });
234	    p.longopt("clarity",
235	              [&](const std::string_view s) { args.clarity_file = s; });
236	    p.longopt("kanata-loop-start", [&](const std::string_view s) {
237	      try {
238	        args.kanata_loop_start = std::stoull(std::string{s}, nullptr, 0);
239	      } catch (...) {
240	        throw std::runtime_error("invalid --kanata-loop-start: "
241	                                 + std::string{s});
242	      }
243	    });
244	    p.longopt("kanata-loop-end", [&](const std::string_view s) {
245	      try {
246	        args.kanata_loop_end = std::stoull(std::string{s}, nullptr, 0);
247	      } catch (...) {
248	        throw std::runtime_error("invalid --kanata-loop-end: "
249	                                 + std::string{s});
250	      }
251	    });
252	    p.longopt("kanata-loop-skip", [&](const std::string_view s) {
253	      try {
254	        args.kanata_loop_skip = std::stoull(std::string{s}, nullptr, 0);
255	      } catch (...) {
256	        throw std::runtime_error("invalid --kanata-loop-skip: "
257	                                 + std::string{s});
258	      }
259	    });
260	    p.longopt("kanata-loop-record", [&](const std::string_view s) {
261	      try {
262	        args.kanata_loop_record = std::stoull(std::string{s}, nullptr, 0);
263	      } catch (...) {
264	        throw std::runtime_error("invalid --kanata-loop-record: "
265	                                 + std::string{s});
266	      }
267	    });
268	    p.longflag("kanata-roi", [&] { args.kanata_roi = true; });
269	    p.longflag("continue", [&] { args.continue_ctx = true; });
270	    p.longflag("save", [&] { args.save_ctx = true; });
271	    p.longopt("context-dir",
272	              [&](const std::string_view s) { args.context_dir = s; });
273	    p.longopt("shared-mem-path",
274	              [&](const std::string_view s) { args.shared_mem_path = s; });
275	    // Shared uint64 longopt handler: parse with 0x/0 prefixes, else throw a
276	    // uniform "invalid --<flag>". Replaces six identical try/catch blocks.
277	    auto u64_opt = [](const char* flag, auto& dest) {
278	      return [flag, &dest](std::string_view s) {
279	        try {
280	          dest = std::stoull(std::string{s}, nullptr, 0);
281	        } catch (...) {
282	          throw std::runtime_error(std::string{"invalid --"} + flag + ": "
283	                                   + std::string{s});
284	        }
285	      };
286	    };
287	    p.longopt("shared-mem-size", u64_opt("shared-mem-size", args.shared_mem_size));
288	    p.longopt("shared-mem-base", u64_opt("shared-mem-base", args.shared_mem_base));
289	    p.longopt("resume-from-qemu", [&](const std::string_view s) {
290	      args.resume_from_qemu = s;
291	    });
292	    p.longopt("handoff-out", [&](const std::string_view s) {
293	      args.handoff_out = s;
294	    });
295	    p.longopt("hybrid-enter-pc", u64_opt("hybrid-enter-pc", args.hybrid_enter_pc));
296	    p.longopt("hybrid-exit-pc", u64_opt("hybrid-exit-pc", args.hybrid_exit_pc));
297	    p.longopt("hybrid-icount", u64_opt("hybrid-icount", args.hybrid_icount));
298	    p.longopt("vsim-warmup-icount",
299	              u64_opt("vsim-warmup-icount", args.vsim_warmup_icount));
300	    p.longopt("reset-vector", [&](const std::string_view s) {
301	      args.reset_vectors.emplace_back(s);
302	    });
303	    p.posarg([&](const std::string_view s) { args.elf_file = s; });
304	    p.parse(std::vector<std::string_view>(argv, argv + argc));
305	    return args;
306	  }();
307	
308	#ifndef VSIMSAVABLE
309	  if (args.save_ctx || args.continue_ctx || args.context_dir != "./saved_ctx/")
310	  {
311	    spdlog::critical(
312	      "--save, --continue, and --context-dir require VSIMSAVABLE build");
313	    std::exit(EXIT_FAILURE);
314	  }
315	#endif
316	
317	  if (!args.resume_from_qemu.empty() && args.continue_ctx)
318	    throw std::runtime_error(
319	      "--resume-from-qemu and --continue are mutually exclusive");
320	
321	  print_version();
322	
323	  // systemc and cci init
324	  auto broker = cci_utils::broker{"global_broker"};
325	  cci::cci_register_broker(broker);
326	
327	  const auto time_resolution = sc_core::sc_get_time_resolution();
328	  spdlog::debug("Using time resolution: {}", time_resolution.to_string());
329	
330	  std::optional<MmapBacking> shared_ram;
331	  if (!args.shared_mem_path.empty()) {
332	    if (args.shared_mem_size == 0)
333	      throw std::runtime_error(
334	        "--shared-mem-path requires --shared-mem-size > 0");
335	    shared_ram.emplace(args.shared_mem_path, args.shared_mem_size);
336	  } else if (args.shared_mem_size != 0) {
337	    throw std::runtime_error(
338	      "--shared-mem-size requires --shared-mem-path");
339	  }
340	
341	  // Hybrid mode: the mmap window is the only RAM; QEMU virt has no alias.
342	  const MemoryRegion ram_region = shared_ram
343	    ? MemoryRegion{args.shared_mem_base,
344	                   args.shared_mem_base + args.shared_mem_size - 1}
345	    : MemoryRegion{RAM_BASE, RAM_END};
346	  const MemoryRegion ram_alias_region = shared_ram
347	    ? MemoryRegion{SimpleMemory<32>::INVALID_ADDRESS,
348	                   SimpleMemory<32>::INVALID_ADDRESS}
349	    : MemoryRegion{RAM_ALIAS_BASE, RAM_ALIAS_END};
350	
351	  // run simulation
352	  const auto do_sim = [&]<typename CPU>() -> int {
353	    Simulator<CPU> sim{
354	      "sim",
355	      shared_ram ? shared_ram->span() : std::span<uint8_t>{},
356	      ram_region, ram_alias_region};
357	
358	    if (args.memmap) {
359	      sim.platform.interconnect.dump_region();
360	      return 0;
361	    }
362	
363	    sim.set_mem_latency(args.mem_latency);
364	
365	    if (!args.ilm_file.empty())
366	      sim.load_image(args.ilm_file, MEM_TYPE::ILM);
367	
368	    if (!args.dlm_file.empty())
369	      sim.load_image(args.dlm_file, MEM_TYPE::DLM);
370	
371	    // End of elaboration
372	    sc_core::sc_start(sc_core::SC_ZERO_TIME);
373	
374	    const auto t0 = std::chrono::steady_clock::now();
375	
376	    if (!args.waveform_file.empty())
377	      sim.enable_waveform(args.waveform_file);
378	
379	    if (!args.pc_trace_file.empty())
380	      sim.enable_pc_trace(args.pc_trace_file);
381	
382	    if (!args.kanata_file.empty() && !args.clarity_file.empty())
383	      throw std::runtime_error("--kanata and --clarity are mutually exclusive");
384	
385	    std::optional<kanata::LoopGate> loop_gate;
386	    if (args.kanata_loop_start.has_value()
387	        != args.kanata_loop_end.has_value())
388	      throw std::runtime_error(
389	        "--kanata-loop-start and --kanata-loop-end must be specified together");
390	    if (args.kanata_loop_start.has_value()) {
391	      if (args.kanata_file.empty() && args.clarity_file.empty())
392	        throw std::runtime_error(
393	          "--kanata-loop-* requires --kanata or --clarity");
394	      if (args.kanata_loop_record == 0)
395	        throw std::runtime_error("--kanata-loop-record must be >= 1");
396	      loop_gate = kanata::LoopGate{*args.kanata_loop_start,
397	                                   *args.kanata_loop_end,
398	                                   args.kanata_loop_skip,
399	                                   args.kanata_loop_record};
400	    }
401	
402	    // --kanata-roi defers kanata enable until after resume + handoff setup so
403	    // the gate can be auto-derived from the resumed PC + CsrTrigger / exit PC.
404	    if (args.kanata_roi) {
405	      if (args.kanata_file.empty())
406	        throw std::runtime_error("--kanata-roi requires --kanata <file>");
407	      if (loop_gate)
408	        throw std::runtime_error(
409	          "--kanata-roi and --kanata-loop-* are mutually exclusive");
410	      if (!args.clarity_file.empty())
411	        throw std::runtime_error("--kanata-roi is not supported with --clarity");
412	      if (args.hybrid_icount)
413	        throw std::runtime_error(
414	          "--kanata-roi is incompatible with --hybrid-icount "
415	          "(no single exit PC); use --mode csr or --mode pc instead");
416	      if (args.resume_from_qemu.empty())
417	        throw std::runtime_error(
418	          "--kanata-roi requires --resume-from-qemu");
419	    }
420	
421	    if (!args.kanata_file.empty() && !args.kanata_roi)
422	      sim.enable_kanata(args.kanata_file, args.objdump_file, loop_gate);
423	
424	    if (!args.clarity_file.empty())
425	      sim.enable_clarity(args.clarity_file, args.objdump_file, loop_gate);
426	
427	    // In tier-2 hybrid resume, QEMU 1 already loaded the ELF into the
428	    // shared mmap. Re-loading would `std::fill_n(memsz - filesz, 0)` over
429	    // each PT_LOAD's .bss tail, wiping phase-1 writes to static buffers.
430	    // Still parse the ELF to set the reset vector -- between sim.reset()
431	    // and apply_resume_from_qemu's DMI halt, the hart fetches one or two
432	    // instructions from the reset vector; if that address is unmapped
433	    // the bus errors leave the hart in a state the resume cannot recover.
434	    const bool elf_already_in_shared_mmap =
435	      !args.resume_from_qemu.empty() && !args.shared_mem_path.empty();
436	    if (!args.elf_file.empty() && !args.continue_ctx)
437	      sim.load_elf(args.elf_file, /*skip_memory_load=*/elf_already_in_shared_mmap);
438	
439	    // Apply per-hart reset vector overrides (after load_elf sets defaults)
440	    for (const auto& s: args.reset_vectors) {
441	      auto [hart, addr] = parse_reset_vector(s);
442	      if (hart) {
443	        sim.set_reset_vector(*hart, addr);
444	      } else {
445	        for (size_t i = 0; i < sim.platform.reset_vector.size(); ++i)
446	          sim.set_reset_vector(i, addr);
447	      }
448	    }
449	
450	    if (args.continue_ctx)
451	      spdlog::info("You're resuming program from the given context");
452	
453	    if (args.jtag_port)
454	      sim.init_debug_port(args.jtag_port.value());
455	
456	    if (!args.jtag_port && args.elf_file.empty() && !args.continue_ctx
457	        && args.resume_from_qemu.empty())
458	      throw std::runtime_error(
459	        "Required arg : program, --jtag-port, or --resume-from-qemu");
460	
461	    if (args.continue_ctx || args.save_ctx) {
462	      std::string_view s = args.context_dir;
463	      if (std::filesystem::exists(s) && !std::filesystem::is_directory(s))
464	        throw std::runtime_error("Error: Path " + std::string{s}
465	                                 + " exists but is not a directory.");
466	      if (!std::filesystem::exists(s)) {
467	        try {
468	          std::filesystem::create_directories(s);
469	        } catch (const std::filesystem::filesystem_error& e) {
470	          throw std::runtime_error(std::string{"Failed to create directory: "}
471	                                   + e.what());
472	        }
473	      }
474	      sim.context_config = {args.save_ctx, args.continue_ctx, args.context_dir};
475	    }
476	
477	    sim.reset();
478	
479	    if (!args.resume_from_qemu.empty())
480	      sim.apply_resume_from_qemu(args.resume_from_qemu);
481	
482	    if (args.hybrid_enter_pc)
483	      spdlog::warn("--hybrid-enter-pc=0x{:x} ignored: entry trigger is "
484	                   "QEMU's job (use plugin enter_pc= arg)",
485	                   *args.hybrid_enter_pc);
486	
487	    if (!args.handoff_out.empty()) {
488	      if (args.hybrid_icount && args.hybrid_exit_pc)
489	        throw std::runtime_error(
490	          "--hybrid-icount and --hybrid-exit-pc are mutually exclusive");
491	      if (args.hybrid_icount)
492	        sim.enable_hybrid_icount_handoff(args.handoff_out,
493	                                         *args.hybrid_icount,
494	                                         args.vsim_warmup_icount);
495	      else
496	        sim.enable_hybrid_handoff(args.elf_file, args.handoff_out,
497	                                  args.hybrid_exit_pc, args.vsim_warmup_icount);
498	    }
499	
500	    if (args.kanata_roi)
501	      sim.enable_kanata_roi(args.kanata_file, args.objdump_file,
502	                            args.hybrid_exit_pc);
503	
504	    const int exit_code = sim.run();
505	
506	    sim.cpu.final();
507	
508	    const auto t1 = std::chrono::steady_clock::now();
509	    const auto cycles = sim.get_cycles();
510	    spdlog::info("{} cycles simulated", cycles);
511	    if (cycles > 0) {
512	      const auto ms =
513	        std::chrono::duration_cast<std::chrono::milliseconds>(t1 - t0);
514	      spdlog::info("{}.{:03}s elapsed, {:.3f}Hz", ms.count() / 1000,
515	                   ms.count() % 1000,
516	                   double(cycles) / double(ms.count()) * 1000.0);
517	    }
518	    return exit_code;
519	  };
520	
521	  return do_sim.operator()<VSIM_CPU_INTERFACE_CLASS>();
522	
523	} catch (const std::exception& e) {
524	  spdlog::critical("fatal exception: {}\n", e.what());
525	  std::exit(EXIT_FAILURE);
526	} catch (...) {
527	  std::terminate();
528	}
