203	  // Caller invariant: the CPU must already be out of reset.
204	  void apply_resume_from_qemu(const std::string& path)
205	  {
206	    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
207	      bus{platform.dmi, platform.clk.period()};
208	    hybrid_input_state_ = hybrid::load_state(path);
209	    // Stage V-register bytes into the fixed scratch region of RAM BEFORE
210	    // resume: ResumeDriver's Program-Buffer reload sweep issues vle8.v from
211	    // this region to repopulate v0..v31, so the bytes must be in place first.
212	    // Best-effort: mismatched RAM layouts throw, which is louder than silently
213	    // dropping V state.
214	    if ((hybrid_input_state_->flags & HYBRID_FLAG_V) != 0u) {
215	      hybrid::stage_v_to_scratch(
216	        *hybrid_input_state_,
217	        platform.main_memory.data,
218	        platform.main_memory.region.base_address);
219	    }
220	    hybrid::ResumeDriver driver(bus);
221	    driver.resume(*hybrid_input_state_);
222	  }
