224	  // Builds the DMI bus + warmup snapshot shared by both handoff modes:
225	  // stores the bus in hybrid_dmi_bus_ and returns the snapshot for the caller
226	  // to move into its controller.
227	  auto make_handoff_snapshot(uint64_t vsim_warmup_icount)
228	    -> hybrid::MeasureStartSnapshot
229	  {
230	    hybrid_dmi_bus_ = std::make_unique<
231	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
232	                            PLATFORM::dmi_data_width>>(platform.dmi,
233	                                                       platform.clk.period());
234	    if (vsim_warmup_icount > 0)
235	      spdlog::info("hybrid: warmup window enabled, K={}", vsim_warmup_icount);
236	    return hybrid::MeasureStartSnapshot{vsim_warmup_icount, *hybrid_dmi_bus_};
237	  }
