239	  // Enables the vsim->QEMU handoff drain. After this is set, run() watches
240	  // committed PCs and on retire of a `csrw 0x7C0, *` exit-trigger drains
241	  // architectural state to `state_out_path` and returns kExitHandoffToQemu.
242	  //
243	  // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
244	  // mode) and the ELF scan is skipped: the binary need not contain a magic
245	  // csrwi marker. CSR mode and PC mode are mutually exclusive on a single
246	  // run -- callers pass exactly one form.
247	  void enable_hybrid_handoff(const std::string& elf_path,
248	                             const std::string& state_out_path,
249	                             std::optional<uint64_t> exit_pc = std::nullopt,
250	                             uint64_t vsim_warmup_icount = 0)
251	  {
252	    hybrid::CsrTrigger trigger;
253	    if (exit_pc) {
254	      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
255	      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
256	    } else {
257	      auto elf = LIEF::ELF::Parser::parse(elf_path);
258	      if (!elf)
259	        throw std::runtime_error(
260	          "enable_hybrid_handoff: failed to parse " + elf_path);
261	      for (const auto& seg: elf->segments()) {
262	        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
263	        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
264	        const auto content = seg.content();
265	        const std::span<const uint8_t> bytes{content.data(), content.size()};
266	        trigger.scan_buffer(bytes, seg.virtual_address());
267	      }
268	    }
269	
270	    auto snapshot = make_handoff_snapshot(vsim_warmup_icount);
271	    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
272	                            std::move(snapshot));
273	    if (hybrid_input_state_)
274	      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
275	    hybrid_state_path_ = state_out_path;
276	  }
277	
278	  // icount-trigger variant: drain after `target` committed insns retire,
279	  // regardless of PC. Sibling to enable_hybrid_handoff (which is CSR/PC). The
280	  // two modes are mutually exclusive on a single run -- callers pass at most
281	  // one. Multi-hart out of scope per F6: the trigger counts hart-0 retires.
282	  void enable_hybrid_icount_handoff(const std::string& state_out_path,
283	                                    uint64_t icount_target,
284	                                    uint64_t vsim_warmup_icount = 0)
285	  {
286	    hybrid::IcountTrigger trigger{icount_target};
287	    spdlog::info("hybrid: icount-trigger mode, target={}", icount_target);
288	
289	    auto snapshot = make_handoff_snapshot(vsim_warmup_icount);
290	    hybrid_icount_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
291	                                   std::move(snapshot));
292	    if (hybrid_input_state_)
293	      hybrid_icount_handoff_->set_passthrough_input(*hybrid_input_state_);
294	    hybrid_state_path_ = state_out_path;
295	  }
