309	  // skip_memory_load: parse the ELF and set the reset vector, but leave
310	  // platform.main_memory untouched. Used in tier-2 hybrid resume where
311	  // QEMU 1's -kernel already populated the shared mmap; re-loading would
312	  // zero-fill the .bss tail of each PT_LOAD and destroy phase-1 writes
313	  // to static buffers. The reset vector is still set so the hart has a
314	  // valid fetch target during the post-reset cycles that precede the DMI
315	  // halt+DPC-write resume sequence.
316	  void load_elf(const std::string& path, bool skip_memory_load = false)
317	  {
318	    const auto elf = LIEF::ELF::Parser::parse(path);
319	    if (!elf) {
320	      spdlog::critical("Check if it's a valid ELF file path : {}", path);
321	      exit(1);
322	    }
323	
324	    if (!skip_memory_load)
325	      read_elf_into_memory(
326	        *elf,
327	        static_cast<xlen_t>(platform.main_memory.region.base_address),
328	        platform.main_memory.data);
329	    for (auto& rv: platform.reset_vector)
330	      rv.write(elf->entrypoint());
331	  }
