343	  void load_image(const std::string& path, MEM_TYPE type)
344	  {
345	    switch (type) {
346	    case MEM_TYPE::ILM:
347	      if constexpr (requires { cpu.set_ilm({}); }) {
348	        read_binary_file(path, [this](const auto& data) { cpu.set_ilm(data); });
349	      } else {
350	        throw std::runtime_error(
351	          "CPU does not support ILM - cannot load ILM ROM image");
352	      }
353	      break;
354	
355	    case MEM_TYPE::DLM:
356	      if constexpr (requires { cpu.set_dlm({}); }) {
357	        read_binary_file(path, [this](const auto& data) { cpu.set_dlm(data); });
358	      } else {
359	        throw std::runtime_error(
360	          "CPU does not support DLM - cannot load DLM ROM image");
361	      }
362	      break;
363	
364	    case MEM_TYPE::RAM:
365	      read_binary_file(path, [this](const auto& data) {
366	        if (data.size() > platform.main_memory.data.size())
367	          throw std::runtime_error("RAM image size exceeds main memory size");
368	        std::copy(data.begin(), data.end(), platform.main_memory.data.begin());
369	      });
370	      break;
371	
372	    default:
373	      throw std::runtime_error("Unknown memory type");
374	    }
375	  }
