377	  void reset()
378	  {
379	    static constexpr int core_num = CPU::NDS_NHART;
380	    static constexpr int reset_val = (1 << core_num) - 1;
381	
382	    platform.resetn.write(0);
383	    auto saved = context_config;
384	    context_config = {};
385	    this->run(1);
386	    context_config = saved;
387	
388	    for (size_t i = 0; i < platform.reset_vector.size(); ++i)
389	      spdlog::info("hart {} reset vector: {:#x}", i,
390	                   (uint64_t) platform.reset_vector[i].read());
391	
392	    platform.resetn.write(reset_val);
393	
394	    if (context_config.continue_from)
395	      restore_context(context_config.dir);
396	  }
