398	  int run(const uint64_t max_cycles = std::numeric_limits<uint64_t>::max())
399	  {
400	    auto sa = memzeroed<struct sigaction>();
401	    sa.sa_handler = sigint_handler;
402	    sigemptyset(&sa.sa_mask);
403	
404	    auto oact = memzeroed<struct sigaction>();
405	    if (sigaction(SIGINT, &sa, &oact) == -1)
406	      perror("sigaction");
407	
408	    const auto restore_sigint = std::experimental::scope_exit{[&] {
409	      if (sigaction(SIGINT, &oact, nullptr) == -1)
410	        perror("sigaction");
411	    }};
412	
413	    // wait for debugger connections
414	    while (dtm_debug && !dtm.is_connected()) {
415	      dtm.try_accept_socket();
416	      if (ctrlc != 0) {
417	        return 130;
418	      }
419	      sleep(1);
420	    }
421	
422	    [[maybe_unused]]
423	    bool ctx_resuming = context_config.continue_from;
424	    [[maybe_unused]]
425	    bool ctx_triggered = false;
426	
427	    for (auto n = uint64_t{0}; n < max_cycles; ++n) {
428	
429	      if (ctx_resuming) [[unlikely]] {
430	        // Pull up PLIC interrupt signal at the first cycle of the resume
431	        platform.int_trigger.write(1);
432	        ctx_resuming = false;
433	        ctx_triggered = true;
434	      }
435	
436	      sc_core::sc_start(platform.clk.period());
437	
438	      trace_.on_cycle(cpu);
439	
440	      if (hybrid_handoff_ || hybrid_icount_handoff_) [[unlikely]] {
441	        if (auto code = check_hybrid_handoff(); code) return *code;
442	      }
443	
444	      if (trace_.pipeview_wants_exit()) {
445	        spdlog::info("Pipeline viewer requested exit (Kanata loop window complete)");
446	        return 0;
447	      }
448	
449	      if (context_config.save_on_wfi && platform.wfi_signal.read() == true)
450	        [[unlikely]]
451	      {
452	        context_config.save(platform, cpu);
453	        spdlog::info("User save context");
454	        return 0;
455	      }
456	
457	      if (ctrlc != 0) {
458	        ctrlc = 0;
459	        spdlog::info("Ctrl+C PC: {:x}", get_current_pc());
460	        trace_.log_committed_pcs(cpu);
461	        return 130;
462	      }
463	
464	      if (ctx_triggered) [[unlikely]] {
465	        // Pull down the interrupt signal after 1 cycle
466	        platform.int_trigger.write(0);
467	        ctx_triggered = false;
468	      }
469	
470	      if (platform.sim_control.exits >= 0) {
471	        spdlog::info("sim_control: got exit {}, stopping",
472	                     platform.sim_control.exits);
473	        spdlog::info("Exit PC: {:x}", get_current_pc());
474	        trace_.log_committed_pcs(cpu);
475	        return platform.sim_control.exits;
476	      }
477	
478	      if (this->cpu.contextp()->gotFinish())
479	        return 0;
480	
481	      spdlog::trace("PC: {:x}", get_current_pc());
482	    }
483	    return 0;
484	  }
