486	  uint64_t get_current_pc()
487	  {
488	    if constexpr (requires { cpu.get_current_pc(); }) {
489	      return cpu.get_current_pc();
490	    }
491	    return std::numeric_limits<uint64_t>::max();
492	  }
493	
494	  auto check_hybrid_handoff() -> std::optional<int>
495	  {
496	    if constexpr (!requires { cpu.get_committed_pc(); }) {
497	      return std::nullopt;
498	    } else {
499	      const auto committed = cpu.get_committed_pc();
500	      if (committed.empty()) return std::nullopt;
501	      auto gpr_probe = [&](uint8_t r) -> uint64_t {
502	        if constexpr (requires { cpu.get_gpr(r); }) {
503	          return cpu.get_gpr(r);
504	        }
505	        return 0;
506	      };
507	      for (const auto pc: committed[0]) {
508	        auto state = std::optional<hybrid_state_v1>{};
509	        if (hybrid_handoff_)
510	          state = hybrid_handoff_->on_retire(pc, gpr_probe);
511	        else if (hybrid_icount_handoff_)
512	          state = hybrid_icount_handoff_->on_retire(pc, gpr_probe);
513	        if (state) {
514	          // V-register merge: the fixture's vsim-phase epilogue is expected
515	          // to have run vse8.v v0..v31 to scratch RAM before the exit
516	          // trigger fired. Read those bytes back into state.vreg[] so the
517	          // gdbstub-driven QEMU 2 restore sees vsim's actual values, not
518	          // QEMU 1's stale snapshot.
519	          if ((state->flags & HYBRID_FLAG_V) != 0u) {
520	            hybrid::read_v_from_scratch(
521	              *state,
522	              std::span<const uint8_t>{platform.main_memory.data.data(),
523	                                       platform.main_memory.data.size()},
524	              platform.main_memory.region.base_address);
525	          }
